{"path":"storage.py","content":"import json
import os

def add_note(note):
    notes = get_notes()
    notes.append(note)
    save_notes(notes)

def get_notes():
    if not os.path.exists('notes.json'):
        return []
    with open('notes.json', 'r') as f:
        return json.load(f)

def save_notes(notes):
    with open('notes.json', 'w') as f:
        json.dump(notes, f, indent=4)

def search_notes(keyword):
    notes = get_notes()
    return [note for note in notes if keyword.lower() in note.lower()]

def delete_note(index):
    notes = get_notes()
    if 0 <= index < len(notes):
        del notes[index]
        save_notes(notes)
"}

{"path":"cli.py","content":"import sys
from storage import add_note, get_notes, search_notes, delete_note

def main():
    if len(sys.argv) < 2:
        print("Использование: python cli.py [add|list|search|delete] [аргументы]")
        return

    command = sys.argv[1]

    if command == 'add':
        if len(sys.argv) != 3:
            print("Использование: python cli.py add "Заметка")")
        else:
            add_note(sys.argv[2])
            print(f"Заметка добавлена: {sys.argv[2]}")

    elif command == 'list':
        notes = get_notes()
        for i, note in enumerate(notes):
            print(f"{i}: {note}")

    elif command == 'search':
        if len(sys.argv) != 3:
            print("Использование: python cli.py search "Ключевое слово")")
        else:
            results = search_notes(sys.argv[2])
            for i, note in enumerate(results):
                print(f"{i}: {note}")

    elif command == 'delete':
        if len(sys.argv) != 3:
            print("Использование: python cli.py delete <индекс>")")
        else:
            try:
                index = int(sys.argv[2])
                delete_note(index)
                print(f"Заметка с индексом {index} удалена.")
